  const hits = await retrieve(env, topic || "n\u1ED9i dung ch\xEDnh c\u1EE7a t\xE0i li\u1EC7u", opts.docIds, 8);
  if (!hits.length) throw new Error("Ch\u01B0a c\xF3 t\xE0i li\u1EC7u \u0111\u1EC3 t\u1EA1o k\u1ECBch b\u1EA3n \u2014 h\xE3y upload tr\u01B0\u1EDBc");
