  const user = `T\xC0I LI\u1EC6U:
${context}

Y\xCAU C\u1EA6U: Vi\u1EBFt l\u1EDDi b\xECnh video kho\u1EA3ng ${words} t\u1EEB (~${durationSec} gi\xE2y \u0111\u1ECDc). Phong c\xE1ch: ${style}. ` + (topic ? `Ch\u1EE7 \u0111\u1EC1 tr\u1ECDng t\xE2m: ${topic}.` : "");
