app.put("/api/studio/upload/:kind", async (c) => {
  const kind = c.req.param("kind");
  const allowed = ["audio", "videos", "segments", "docs", "images"];
  const folder = allowed.includes(kind) ? kind : "segments";
  const contentType = c.req.header("content-type") || "application/octet-stream";
  const name = (c.req.query("name") || "").replace(/[^\w.\-]/g, "_").slice(0, 80);
  const bytes2 = await c.req.arrayBuffer();
  if (!bytes2 || bytes2.byteLength < 64) return c.json(bad("D\u1EEF li\u1EC7u file kh\xF4ng h\u1EE3p l\u1EC7"), 400);
  if (bytes2.byteLength > 4 * 1024 * 1024) {
    return c.json(bad("File tr\xEAn 4MB ph\u1EA3i upload tr\u1EF1c ti\u1EBFp l\xEAn Vercel Blob"), 413);
  }
  const ext = (name.includes(".") ? name.split(".").pop() : "") || (contentType.includes("mp4") ? "mp4" : contentType.includes("mpeg") ? "mp3" : "bin");
  const key = `${folder}/${uid("st_")}.${ext}`;
  const saved = await putAsset(c.env, key, bytes2, contentType);
  return c.json({ url: saved.url, key, size: saved.size, name: name || key });
});
