app.post("/api/studio/srt/translate", async (c) => {
  const body = await c.req.json().catch(() => ({}));
  const target = String(body.target_lang || "vi");
  const model = body.model ? String(body.model) : void 0;
  try {
    if (Array.isArray(body.segments) && body.segments.length) {
      const segs = body.segments.slice(0, 400);
      const res2 = await translateTexts(
        c.env,
        segs.map((s) => String(s.text || "").replace(/\n/g, " ")),
        target,
        model
      );
      const out = segs.map((s, i) => ({
        start: Number(s.start) || 0,
        end: Number(s.end) || 0,
        text: res2.texts[i]
      }));
      return c.json({
        segments: out,
        srt: composeSRT(out),
        cue_count: out.length,
        translated_lines: res2.translated_lines,
        batches: res2.batches,
        llm: res2.llm,
        target_lang: target
      });
    }
    const srt = String(body.srt || "");
    if (!srt.trim()) return c.json(bad("Ch\u01B0a c\xF3 n\u1ED9i dung SRT"), 400);
    const res = await translateSRT(c.env, srt, target, model);
    return c.json(res);
  } catch (e) {
    return c.json(bad(`D\u1ECBch th\u1EA5t b\u1EA1i: ${String(e?.message || e).slice(0, 200)}`, 502), 502);
  }
});
